def answer_query(principal, query):
    roles = memberships.roles_for(principal)
    if not roles:
        raise PermissionError('TENANT_MEMBERSHIP_REQUIRED')
    candidates = store.search(principal, query, memberships, top_k=5)  # filters before ranking
    if not candidates:
        return RagAnswer('ABSTAIN_NO_EVIDENCE', (), 'No authorized evidence found.')
    citations = tuple(Citation(d.doc_id, d.version, d.page, d.chunk_id) for d in candidates)
    return RagAnswer('ANSWERED', citations, candidates[0].text)

def execute_tool(principal, proposal, approval, idempotency_key):
    return tool_gateway.execute(principal, proposal, approval, idempotency_key)
